<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue';
type Article={stableId:string;slug:string;title:string;description:string;url:string;publishedAt:string};
type HistoryEntry={lastVisitedAt:string;progress:number};
type State={schemaVersion:1;favorites:Record<string,string>;read:Record<string,string>;history:Record<string,HistoryEntry>;preferences:{view:'grid'|'list'}};
type CollectionKind='favorites'|'read'|'history';
const props=defineProps<{articles:Article[];siteId:string;base:string}>();
const key=`learninghub:${props.siteId}:reader:v1`;const state=ref<State>(empty());const message=ref('');const mode=ref<CollectionKind>('favorites');const importMode=ref<'merge'|'replace'>('merge');
function empty():State{return{schemaVersion:1,favorites:{},read:{},history:{},preferences:{view:'grid'}}}
function validDate(value:unknown):value is string{return typeof value==='string'&&Number.isFinite(Date.parse(value))&&/^\d{4}-\d{2}-\d{2}T/.test(value)}
function validRecord(value:unknown,kind:CollectionKind):value is State[CollectionKind]{if(!value||typeof value!=='object'||Array.isArray(value))return false;return Object.entries(value).every(([id,entry])=>/^[a-z0-9][a-z0-9-]*$/.test(id)&& (kind==='history'?!!entry&&typeof entry==='object'&&validDate((entry as HistoryEntry).lastVisitedAt)&&Number.isInteger((entry as HistoryEntry).progress)&&(entry as HistoryEntry).progress>=0&&(entry as HistoryEntry).progress<=100:validDate(entry)))}
function normalize(value:unknown):State|null{if(!value||typeof value!=='object')return null;const parsed=value as Partial<State>;if(parsed.schemaVersion!==1||!validRecord(parsed.favorites,'favorites')||!validRecord(parsed.read,'read')||!validRecord(parsed.history,'history'))return null;return{schemaVersion:1,favorites:parsed.favorites,read:parsed.read,history:parsed.history,preferences:{view:parsed.preferences?.view==='list'?'list':'grid'}}}
function load(){try{const stored=localStorage.getItem(key);if(stored){const parsed=normalize(JSON.parse(stored));if(parsed)state.value=parsed;else message.value='本機閱讀資料格式無效；你仍可繼續瀏覽。'}}catch{message.value='本機閱讀資料無法讀取；你仍可繼續瀏覽。'}}
function save(){try{localStorage.setItem(key,JSON.stringify(state.value));message.value='已儲存於此瀏覽器。'}catch{message.value='瀏覽器空間不足，這次變更只保留在目前頁面。'}}
function sync(event:StorageEvent){if(event.key!==key)return;if(!event.newValue){state.value=empty();return}try{const next=normalize(JSON.parse(event.newValue));if(next)state.value=next}catch{message.value='另一個分頁的閱讀資料無法讀取。'}}
onMounted(()=>{load();window.addEventListener('storage',sync)});onUnmounted(()=>window.removeEventListener('storage',sync));
const records=computed(()=>{const source=state.value[mode.value];const timestamp=(value:string|HistoryEntry)=>typeof value==='string'?value:value.lastVisitedAt;return Object.entries(source).map(([id,value])=>({article:props.articles.find(item=>item.stableId===id),id,value})).filter(item=>item.article).sort((a,b)=>timestamp(b.value).localeCompare(timestamp(a.value))||a.id.localeCompare(b.id))});
function remove(id:string){delete state.value[mode.value][id];save()}
function clear(){if(!confirm('確定清除這台瀏覽器的所有閱讀資料？此操作無法復原。'))return;state.value=empty();save()}
function exportData(){const blob=new Blob([JSON.stringify(state.value,null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='learninghub-reading-data.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),0)}
function newer(left:string,right:string){return Date.parse(left)>=Date.parse(right)}
async function importData(event:Event){const inputElement=event.target as HTMLInputElement;const file=inputElement.files?.[0];if(!file)return;if(file.size>1024*1024){message.value='檔案超過 1MB，未匯入。';inputElement.value='';return}try{const imported=normalize(JSON.parse(await file.text()));if(!imported)throw new Error('invalid');const operation=importMode.value==='merge'?'合併（同一文章保留較新的時間）':'覆蓋目前閱讀資料';if(!confirm(`確定${operation}？匯入的未知文章 ID 會保留在資料中。`))return;if(importMode.value==='replace')state.value=imported;else{for(const kind of ['favorites','read'] as const)for(const [id,date] of Object.entries(imported[kind]))if(!state.value[kind][id]||newer(date,state.value[kind][id]))state.value[kind][id]=date;for(const [id,entry] of Object.entries(imported.history))if(!state.value.history[id]||newer(entry.lastVisitedAt,state.value.history[id].lastVisitedAt))state.value.history[id]=entry;state.value.preferences=imported.preferences;}const recent=Object.entries(state.value.history).sort((a,b)=>b[1].lastVisitedAt.localeCompare(a[1].lastVisitedAt)).slice(0,200);state.value.history=Object.fromEntries(recent);save()}catch{message.value='資料格式不正確，未匯入。'}finally{inputElement.value=''}}
</script>
<template>
  <section class="library-view">
    <div class="library-toolbar"><div class="library-tabs" role="tablist" aria-label="閱讀資料"><button v-for="option in [['favorites','收藏'],['read','已讀'],['history','近期瀏覽']]" :key="option[0]" role="tab" :aria-selected="mode===option[0]" @click="mode=option[0] as CollectionKind">{{ option[1] }} <span>{{ Object.keys(state[option[0] as CollectionKind]).length }}</span></button></div><div class="library-tools"><button type="button" @click="exportData">匯出資料</button><label>匯入方式<select v-model="importMode" aria-label="匯入方式"><option value="merge">合併</option><option value="replace">覆蓋</option></select></label><label class="file-button">匯入資料<input type="file" accept="application/json,.json" @change="importData" /></label><button type="button" @click="clear">清除資料</button></div></div>
    <p class="storage-note" aria-live="polite">{{ message || '資料只儲存在此瀏覽器，沒有跨裝置同步。' }}</p>
    <div v-if="records.length" class="library-list"><article v-for="item in records" :key="item.id" class="library-row"><a :href="item.article!.url"><strong>{{ item.article!.title }}</strong><span>{{ item.article!.description }}</span><small>{{ typeof item.value==='string'?item.value:item.value.lastVisitedAt }}<template v-if="typeof item.value!=='string'"> · 閱讀進度 {{ item.value.progress }}%</template></small></a><button type="button" :aria-label="`移除${item.article!.title}`" @click="remove(item.id)">移除</button></article></div><div v-else class="empty-state">這裡還沒有{{ mode==='favorites'?'收藏文章':mode==='read'?'已讀文章':'瀏覽紀錄' }}。前往文章頁即可開始累積。</div>
  </section>
</template>
